Bloqueo geográfico.ejemplo:
# Regla Nginx con GeoIP2 para restringir acceso administrativo por país
geoip2 /etc/nginx/GeoLite2-Country.mmdb {
    $geoip2_data_country_code country iso_code;
}
map $geoip2_data_country_code $allowed_country {
    default no;
    ES yes;
}
# En location /admin: if ($allowed_country = no) { return 403; }

Cloudflare.ejemplo:
# Regla Nginx en origen para confiar en la IP real enviada por Cloudflare
# (combinar siempre con bloqueo a nivel de firewall fuera de rangos Cloudflare)
real_ip_header CF-Connecting-IP;
set_real_ip_from 173.245.48.0/20;
set_real_ip_from 103.21.244.0/22;

Firewall de red.ejemplo:
# Ejemplo de reglas stateful básicas con nftables en Linux (política drop por defecto)
table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
    iif "lo" accept
    tcp dport 443 accept
  }
}

Protección DDoS.ejemplo:
# Ejemplo conceptual de mitigación básica en Nginx frente a slowloris/conexiones lentas
client_body_timeout 10s;
client_header_timeout 10s;
send_timeout 10s;
limit_conn_zone $binary_remote_addr zone=addr:10m;
limit_conn addr 20;

Proxy inverso.ejemplo:
# Configuración segura básica de proxy inverso en Nginx
server {
  listen 443 ssl http2;
  server_name api.ejemplo.com;
  client_max_body_size 2m;
  location / {
    proxy_pass https://backend_upstream;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto $scheme;
  }
}
